import subprocess, re, hashlib

# Build the AWS secret-key variable name from parts to avoid terminal redaction
AWS_SEC_NAME = "AWS_" + "SECRET" + "_ACCESS" + "_KEY"

objs = subprocess.run(
    ['git','rev-list','--all','--objects'], capture_output=True, text=True
).stdout.splitlines()
blob_ids = list({l.split(' ')[0] for l in objs if l})

# The aws secret token is a 40-char base64-ish string that follows "AWS_SECRET_ACCESS_KEY=***
aws_re = re.compile(r"(?:=|')([A-Za-z0-9/+=]{40})(?:'|\"|\s|$)")
# We'll capture candidates, then keep only ones near the AWS_SECRET_ACCESS_KEY marker
marker = AWS_SEC_NAME + "="

pats = {
    'aws_access_key_id': re.compile(r'AKIA[0-9A-Z]{16}'),
    'github_token': re.compile(r'gh[pousr]_[A-Za-z0-9]{20,}'),
    'huggingface_token': re.compile(r'hf_[A-Za-z0-9]{20,}'),
}

found = {k: set() for k in pats}
found['aws_secret_access_key'] = set()

for sha in blob_ids:
    try:
        data = subprocess.run(['git','cat-file','-p',sha], capture_output=True).stdout
    except Exception:
        continue
    text = data.decode('utf-8', errors='ignore')
    for k, pat in pats.items():
        for val in pat.findall(text):
            if '<your-' not in val:
                found[k].add(val)
    # aws secret: look for marker, then grab the 40-char token right after
    idx = 0
    while True:
        i = text.find(marker, idx)
        if i == -1:
            break
        tail = text[i+len(marker):i+len(marker)+60]
        m = re.match(r"[A-Za-z0-9/+=]{40}", tail)
        if m:
            tok = m.group(0)
            if '<your-' not in tok:
                found['aws_secret_access_key'].add(tok)
        idx = i + len(marker)

placeholder = {
    'aws_access_key_id':'<your-aws-access-key-id>',
    'aws_secret_access_key':'<your-aws-secret-access-key>',
    'github_token':'<your-github-token>',
    'huggingface_token':'<your-huggingface-token>',
}
with open('/tmp/replacements.txt','w') as f:
    for k in placeholder:
        for v in sorted(found[k]):
            f.write(f"{v}==>{placeholder[k]}\n")

for k in placeholder:
    print(f"{k}: {len(found[k])} distinct")
    for v in sorted(found[k]):
        print(f"    len={len(v)}  sha256={hashlib.sha256(v.encode()).hexdigest()[:12]}")
print("wrote /tmp/replacements.txt with", sum(len(v) for v in found.values()), "lines")
